#!/usr/bin/env bash
# apply-l1-widget-fixes.sh
#
# Applies the L1 Copilot widget-parity fixes directly (no git apply / patch
# matching -- this repo's automated patch history has been unreliable with
# whitespace-sensitive diffs, so this script performs the actual file
# operations instead and is safe to re-run: it skips any page that already
# has the widget, and overwrites the two new test files with the same
# content each time).
#
# What it does:
#   1. Inserts the L1 Copilot assistant widget fragment (CSS+HTML+JS,
#      already present on l1-ticket-copilot.html) into
#      enterprise-command-center.html and vmware-copilot.html, right
#      before </body>. Idempotent -- skipped if #l1a-fab already exists.
#   2. Writes tests/e2e/demo/l1-platform-demo.spec.js (3-stop version,
#      topology.html intentionally excluded -- see comment in the file).
#   3. Writes tests/e2e/demo/preflight-l1-platform-demo.sh and makes it
#      executable.
#   4. Runs verification: script-tag balance, closing-tag check, selector
#      presence, and a node --check syntax check on the spec.
#
# Usage:
#   bash apply-l1-widget-fixes.sh [path-to-tsm-rcm-repo]
#   (defaults to the current directory if no path is given)

set -euo pipefail

REPO_DIR="${1:-.}"
L1_DIR="$REPO_DIR/html/l1-copilot"
DEMO_DIR="$REPO_DIR/tests/e2e/demo"

if [[ ! -d "$L1_DIR" ]]; then
  echo "✗ $L1_DIR not found -- pass the path to your tsm-rcm repo root as the first argument."
  echo "  e.g. bash apply-l1-widget-fixes.sh ~/projects/tsm-rcm"
  exit 1
fi

echo "Applying L1 Copilot widget fixes to: $REPO_DIR"
echo "========================================"

mkdir -p "$DEMO_DIR"

# ── Payload 1: the widget fragment (CSS+HTML+JS), base64-encoded to avoid
#    any shell-quoting hazards from its own content. ────────────────────
echo "" | base64 -d > /tmp/l1a-widget-fragment.html

# ── Payload 2: full replacement for the demo spec ────────────────────────
echo "" | base64 -d > "$DEMO_DIR/l1-platform-demo.spec.js"
echo "✓ wrote $DEMO_DIR/l1-platform-demo.spec.js"

# ── Payload 3: full replacement for the preflight checker ───────────────
echo "" | base64 -d > "$DEMO_DIR/preflight-l1-platform-demo.sh"
chmod +x "$DEMO_DIR/preflight-l1-platform-demo.sh"
echo "✓ wrote $DEMO_DIR/preflight-l1-platform-demo.sh (executable)"

echo ""
echo "── Inserting widget into pages that don't have it yet ──"

REPO_DIR="$REPO_DIR" python3 << 'PYEOF2'
import os

repo_dir = os.environ["REPO_DIR"]
widget = open("/tmp/l1a-widget-fragment.html").read()

targets = [
    os.path.join(repo_dir, "html/l1-copilot/enterprise-command-center.html"),
    os.path.join(repo_dir, "html/l1-copilot/vmware-copilot.html"),
]

for path in targets:
    if not os.path.exists(path):
        print(f"  ✗ {path} not found -- skipping")
        continue
    content = open(path, encoding="utf-8").read()
    if 'id="l1a-fab"' in content:
        print(f"  · {path}: widget already present, left unchanged")
        continue
    if "</body>" not in content:
        print(f"  ✗ {path}: no </body> found -- needs manual handling, skipped")
        continue
    idx = content.rfind("</body>")
    new_content = content[:idx] + widget + "\n" + content[idx:]
    with open(path, "w", encoding="utf-8") as f:
        f.write(new_content)
    print(f"  ✓ {path}: widget inserted before </body>")
PYEOF2

echo ""
echo "── Verifying ──"

for f in "$L1_DIR/enterprise-command-center.html" "$L1_DIR/l1-ticket-copilot.html" "$L1_DIR/vmware-copilot.html"; do
  name=$(basename "$f")
  if [[ ! -f "$f" ]]; then
    echo "  ✗ $name: file not found"
    continue
  fi
  open_tags=$(grep -o '<script' "$f" | wc -l)
  close_tags=$(grep -o '</script>' "$f" | wc -l)
  has_fab=$(grep -c 'id="l1a-fab"' "$f" || true)
  ends_html=$(tail -c 200 "$f" | grep -c '</html>' || true)

  status="OK"
  [[ "$open_tags" -ne "$close_tags" ]] && status="SCRIPT TAG MISMATCH"
  [[ "$has_fab" -eq 0 ]] && status="MISSING WIDGET"
  [[ "$ends_html" -eq 0 ]] && status="MISSING </html> AT END"

  echo "  $name: <script>=$open_tags </script>=$close_tags widget=$has_fab ends-with-</html>=$ends_html -> $status"
done

echo ""
if command -v node >/dev/null 2>&1; then
  if node --check "$DEMO_DIR/l1-platform-demo.spec.js" 2>&1; then
    echo "  ✓ l1-platform-demo.spec.js syntax OK"
  fi
else
  echo "  · node not found on PATH -- skipped spec syntax check"
fi

echo ""
echo "========================================"
echo "Done. Next steps:"
echo "  TSM_BASE_URL=http://localhost:8080 bash $DEMO_DIR/preflight-l1-platform-demo.sh"
echo "  npx playwright test $DEMO_DIR/l1-platform-demo.spec.js"
echo "  bash $DEMO_DIR/build-video.sh l1-platform"